program Factorial;

{$APPTYPE CONSOLE}

function Fact(N: Integer): Int64;
begin
  if N <= 1 then
    Result := 1
  else
    Result := N * Fact(N - 1);
end;

begin
  Writeln(Fact(10));
end.

