program Events;

{$APPTYPE CONSOLE}

type
  TChangeEvent = procedure(Sender: TObject; Value: Integer) of object;

  TThermostat = class
  private
    FTemp: Integer;
    FOnChange: TChangeEvent;
    procedure SetTemp(Value: Integer);
  public
    property Temp: Integer read FTemp write SetTemp;
    property OnChange: TChangeEvent read FOnChange write FOnChange;
  end;

  TDisplay = class
    procedure Show(Sender: TObject; Value: Integer);
  end;

procedure TThermostat.SetTemp(Value: Integer);
begin
  if Value = FTemp then Exit;
  FTemp := Value;
  if Assigned(FOnChange) then FOnChange(Self, Value);  { fire the event }
end;

procedure TDisplay.Show(Sender: TObject; Value: Integer);
begin
  Writeln(Sender.ClassName, '.Temp = ', Value);
end;

var
  T: TThermostat;
  D: TDisplay;
begin
  T := TThermostat.Create;
  D := TDisplay.Create;
  try
    T.Temp := 18;           { no handler yet: nothing happens }
    T.OnChange := D.Show;   { a method pointer binds object + method }
    T.Temp := 21;
    T.Temp := 21;           { same value: the setter fires no event }
    T.Temp := 23;
  finally
    D.Free;
    T.Free;
  end;
end.
